insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_econfe_v1'
from (values
('113.31.d.1.A ',2,'A town has $2 million to spend and requests totaling $5 million. Which concept does this situation illustrate?','["Scarcity forces choices", "Perfect competition", "Zero opportunity cost", "Unlimited resources"]'::jsonb,0,'Wants exceed resources, so every society must choose.','original'),
('113.31.d.1.A ',2,'Why is scarcity faced by every society, rich or poor?','["Goods are free", "Resources are limited while wants are unlimited", "Money is illegal", "Wants are limited"]'::jsonb,1,'Limited resources and unlimited wants create scarcity.','original'),
('113.31.d.1.B',2,'Which question is one of the three basic economic questions every society answers?','["What time school starts", "Which movie is best", "What goods and services to produce", "Which team will win"]'::jsonb,2,'Societies decide what, how and for whom to produce.','original'),
('113.31.d.1.B',3,'In a command economy, who mainly answers "what to produce"?','["Competing firms", "Foreign banks", "Individual consumers", "The central government"]'::jsonb,3,'Central planners make the decisions.','original'),
('113.31.d.1.C',2,'A bakery''s ovens and mixers are an example of which factor of production?','["Capital", "Entrepreneurship", "Land", "Labor"]'::jsonb,0,'Capital is human-made goods used to produce other goods.','original'),
('113.31.d.1.C',2,'A person who starts a new company and takes on its risk is providing which factor of production?','["Land", "Entrepreneurship", "Labor only", "Capital"]'::jsonb,1,'Entrepreneurs organize resources and take risks.','original'),
('113.31.d.1.D',3,'On a production-possibilities curve, a point inside the curve shows that the economy is doing what?','["Producing impossible output", "Producing at maximum capacity", "Using resources inefficiently or leaving some unused", "Operating with no scarcity"]'::jsonb,2,'Points inside the curve are attainable but inefficient.','original'),
('113.31.d.1.D',3,'Moving along a production-possibilities curve to produce more of one good means producing less of another. This trade-off is called what?','["A subsidy", "Comparative advantage", "Inflation", "Opportunity cost"]'::jsonb,3,'The cost is the next best alternative given up.','original'),
('113.31.d.3.A',3,'Producer A gives up 0.5 radio for each shirt it makes. Producer B gives up 1 radio for each shirt. Which has the comparative advantage in shirts?','["The producer with the lower opportunity cost", "Neither can trade", "Both are identical", "The producer with the higher opportunity cost"]'::jsonb,0,'Comparative advantage goes to the lower opportunity cost, which is Producer A.','original'),
('113.31.d.3.A',3,'A country has an absolute advantage in a good when it can do what?','["Produce it at a lower opportunity cost", "Produce it using fewer resources than another country", "Ban its import", "Price it at zero"]'::jsonb,1,'Absolute advantage compares resource use.','original'),
('113.31.d.3.B ',3,'A tariff on imported steel is most likely to do what?','["Increase imports", "Lower the price of imports", "Raise the price of imported steel for domestic buyers", "Eliminate scarcity"]'::jsonb,2,'Tariffs are taxes on imports.','original'),
('113.31.d.3.B ',3,'Which is a benefit of free trade?','["No job changes at all", "Higher prices for all", "Fewer choices", "Consumers gain access to a greater variety of goods at lower prices"]'::jsonb,3,'Trade expands choices.','original'),
('113.31.d.3.C',3,'If the U.S. dollar becomes stronger against the euro, U.S. exports to Europe are likely to do what?','["Become more expensive for Europeans and fall", "Become cheaper and rise", "Stay the same", "Disappear entirely"]'::jsonb,0,'A stronger dollar raises foreign prices.','original'),
('113.31.d.3.C',3,'A weaker dollar tends to cause what to happen to imports?','["They stay fixed", "They become more expensive for Americans", "They become cheaper", "They are banned"]'::jsonb,1,'Imports cost more dollars.','original'),
('113.31.d.4.A',2,'Which feature is a basic characteristic of the free enterprise system?','["No ownership", "Government sets all prices", "Private property rights and the profit incentive", "No competition"]'::jsonb,2,'Free enterprise relies on private ownership and incentives.','original'),
('113.31.d.4.A',2,'In an economic system, an incentive is what?','["A bank", "A tariff", "A tax form", "A reward or penalty that influences behavior"]'::jsonb,3,'Incentives drive choices.','original'),
('113.31.d.4.B',3,'Which economy is best described by central planning and government ownership of nearly all property?','["Communism", "Pure competition", "Mixed market", "Free enterprise"]'::jsonb,0,'Communism features state ownership.','original'),
('113.31.d.4.B',3,'A system with private business and extensive government social programs is best described as what?','["Barter", "Mixed economy", "Pure command", "Pure market"]'::jsonb,1,'Most economies blend market and government roles.','original'),
('113.31.d.4.C',3,'Which economist is known for promoting free markets and limited government in works such as "Capitalism and Freedom"?','["Mao Zedong", "Karl Marx", "Milton Friedman", "Vladimir Lenin"]'::jsonb,2,'Friedman championed free-market ideas.','original'),
('113.31.d.4.C',3,'Adam Smith''s "invisible hand" idea suggests that what happens?','["Government sets prices", "Trade harms nations", "Markets never work", "Self-interested actions in markets can benefit society"]'::jsonb,3,'Smith argued markets guide resources.','original'),
('113.31.d.5.A',2,'Competition among sellers typically benefits consumers by doing what?','["Encouraging lower prices and better quality", "Reducing choices", "Eliminating products", "Raising prices"]'::jsonb,0,'Rivals compete for customers.','original'),
('113.31.d.5.B',3,'Which change shows a shift in the role of government in the U.S. economy since 1900?','["Ending private property", "Growth of regulation and social programs", "Elimination of taxes", "A ban on business"]'::jsonb,1,'Government''s role has expanded.','original'),
('113.31.d.5.B',3,'The Sherman Antitrust Act of 1890 was intended to do what?','["Set minimum wages", "Raise tariffs", "Prevent monopolies that restrain trade", "Create the income tax"]'::jsonb,2,'It targets anticompetitive behavior.','original'),
('113.31.d.6.A',2,'Before buying a $20,000 used truck, a buyer compares insurance, repairs and resale value. This is an example of weighing what?','["Barter", "Subsidies", "Tariffs", "Costs and benefits of property use"]'::jsonb,3,'Cost-benefit analysis guides decisions.','original'),
('113.31.d.6.A',2,'A business must dispose of old equipment. Which cost should it consider?','["Disposal fees or environmental cleanup costs", "No costs exist", "Only the original price", "Only taxes"]'::jsonb,0,'Disposal can carry costs.','original'),
('113.31.d.6.B',3,'Zoning laws that limit a factory near homes are an example of what?','["A subsidy", "Government restrictions on the use of business property", "A tariff", "A barter"]'::jsonb,1,'Government can limit property use.','original'),
('113.31.d.6.B',3,'Eminent domain allows the government to do what?','["Take property without payment", "Ban ownership", "Take private property for public use with fair payment", "Set all prices"]'::jsonb,2,'The Fifth Amendment requires just compensation.','original'),
('113.31.d.7.A',3,'In the circular-flow model, households provide what to firms in the factor market?','["Loans only", "Taxes only", "Goods for free", "Land, labor and capital in exchange for income"]'::jsonb,3,'Households own resources.','original'),
('113.31.d.7.A',3,'In the product market of the circular-flow model, firms provide what?','["Goods and services in exchange for consumer spending", "Wages", "Labor", "Land"]'::jsonb,0,'Firms sell output to households.','original'),
('113.31.d.7.B',3,'When the government collects taxes and buys goods, how does it affect the circular-flow model?','["It ends firms", "It adds a flow of money and resources into and out of the system", "It stops the flow", "It has no effect"]'::jsonb,1,'Government participates in both markets.','original'),
('113.31.d.7.B',3,'Increased government spending in the circular-flow model generally does what to demand for firms'' products?','["Has no effect", "Lowers it to zero", "Increases it", "Eliminates it"]'::jsonb,2,'More spending raises demand.','original'),
('113.31.d.8.A',3,'A market with many small sellers offering nearly identical products, such as a wheat farm market, is called what?','["Monopoly", "Command economy", "Oligopoly", "Pure competition"]'::jsonb,3,'Many sellers, identical goods.','original'),
('113.31.d.8.A',3,'A market with only a few large firms, such as U.S. wireless carriers, is an example of what?','["Oligopoly", "Pure competition", "Barter", "Monopolistic competition"]'::jsonb,0,'A few dominant sellers.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Social Studies' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_econfe_v1'
from (values
('113.31.d.8.B',3,'The Federal Trade Commission regulates market structures mainly by doing what?','["Setting every price", "Enforcing rules against unfair competition and deceptive practices", "Printing money", "Owning companies"]'::jsonb,1,'The FTC promotes fair competition.','original'),
('113.31.d.8.B',3,'Antitrust law applies most directly to which market structure?','["Barter", "Pure competition", "Monopoly", "Household"]'::jsonb,2,'Antitrust curbs monopoly power.','original'),
('113.31.d.9.A',2,'The unemployment rate measures what?','["Interest rates", "The prices of goods", "Total output", "The percentage of the labor force that is jobless and looking for work"]'::jsonb,3,'It excludes those not seeking work.','original'),
('113.31.d.9.B',3,'During a recession, which indicator typically falls?','["Real GDP", "Bankruptcies", "The unemployment rate", "Layoffs"]'::jsonb,0,'Output declines.','original'),
('113.31.d.9.B',3,'A business cycle expansion is typically marked by what?','["Rising joblessness", "Rising output and falling unemployment", "Falling output", "Closing factories"]'::jsonb,1,'Expansion is a growth phase.','original'),
('113.31.d.10.A',3,'Which change increases productivity?','["Wages fall", "Output stays constant", "Workers produce more output per hour", "Workers produce less per hour"]'::jsonb,2,'Productivity is output per input.','original'),
('113.31.d.10.A',3,'Higher productivity usually leads to what?','["Scarcity ending", "Inflation only", "Recession", "Economic growth"]'::jsonb,3,'Producing more per input grows the economy.','original'),
('113.31.d.10.B',3,'New technology such as automated assembly lines contributes to economic growth by doing what?','["Raising output with the same resources", "Ending trade", "Reducing output", "Banning work"]'::jsonb,0,'Technology improves efficiency.','original'),
('113.31.d.10.B',3,'The invention of the Internet affected growth by doing what?','["Ending business", "Creating new industries and boosting efficiency", "Stopping trade", "Raising scarcity"]'::jsonb,1,'Technology spurs growth.','original'),
('113.31.d.10.C',3,'International trade contributes to growth by doing what?','["Banning imports", "Reducing choices", "Expanding markets and allowing specialization", "Ending exports"]'::jsonb,2,'Trade widens markets.','original'),
('113.31.d.10.C',3,'A nation that specializes and trades is likely to experience what?','["Shrinking output", "Higher scarcity", "Zero growth", "A larger overall output of goods and services"]'::jsonb,3,'Specialization increases efficiency.','original'),
('113.31.d.11.A',2,'Money serving as a way to compare the value of a pizza and a bicycle is acting as what?','["A unit of account", "A store of value only", "A barter good", "A loan"]'::jsonb,0,'Money measures value.','original'),
('113.31.d.11.A',2,'Which is NOT a function of money?','["Unit of account", "Producing goods", "Store of value", "Medium of exchange"]'::jsonb,1,'Money does not produce goods.','original'),
('113.31.d.11.B',3,'A $20 bill is worth more than the paper it is printed on because the government declares it legal tender. This is called what?','["Commodity money", "Representative money", "Fiat money", "Barter"]'::jsonb,2,'Fiat money has value by decree.','original'),
('113.31.d.11.B',3,'Gold coins used as money are an example of what?','["A check", "Fiat money", "A debit card", "Commodity money"]'::jsonb,3,'Commodity money has value on its own.','original'),
('113.31.d.11.C',3,'A drawback of barter compared with currency is what?','["It requires a double coincidence of wants", "It is always fair", "It is fast", "It uses money"]'::jsonb,0,'Both parties must want the other''s goods.','original'),
('113.31.d.11.C',3,'A benefit of a debit card is that it does what?','["Charges interest", "Spends money directly from a checking account without creating debt", "Ends fees", "Creates debt"]'::jsonb,1,'Debit pulls from funds on hand.','original'),
('113.31.d.12.A',3,'The Federal Reserve System is made up of how many regional Federal Reserve Banks?','["3", "50", "12", "5"]'::jsonb,2,'There are 12 districts.','original'),
('113.31.d.12.A',3,'Who sets monetary policy in the Federal Reserve System?','["Congress", "The Supreme Court", "The President alone", "The Federal Open Market Committee"]'::jsonb,3,'The FOMC directs open market operations.','original'),
('113.31.d.12.B',3,'Which is one of the Fed''s three basic tools of monetary policy?','["Open market operations", "Printing stock", "Setting income taxes", "Setting wages"]'::jsonb,0,'The others are reserve requirements and the discount rate.','original'),
('113.31.d.12.B',3,'If the Fed raises the reserve requirement, banks must do what?','["Close", "Hold more money in reserve and lend less", "Lend more", "Hold less"]'::jsonb,1,'Lending capacity falls.','original'),
('113.31.d.12.C',3,'When the Fed buys government securities on the open market, the money supply typically does what?','["Disappears", "Decreases", "Increases", "Stays zero"]'::jsonb,2,'The Fed injects money into banks.','original'),
('113.31.d.12.C',3,'Raising the discount rate generally causes what?','["Cheaper loans", "No effect", "More money", "Borrowing to become more expensive for banks and the money supply to tighten"]'::jsonb,3,'Higher rates slow lending.','original'),
('113.31.d.12.D',3,'The U.S. dollar is widely used in world trade, which is why it is called what?','["A major reserve currency", "A barter", "A tariff", "A commodity"]'::jsonb,0,'Many nations hold dollars.','original'),
('113.31.d.12.D',3,'A very strong dollar can hurt U.S. exporters because it does what?','["Makes them cheaper", "Makes their goods more expensive abroad", "Ends trade", "Bans exports"]'::jsonb,1,'Prices abroad rise.','original'),
('113.31.d.13.A',3,'Which is a role of government in the U.S. free enterprise system?','["Owning all firms", "Banning competition", "Protecting property rights and enforcing contracts", "Setting all prices"]'::jsonb,2,'Government provides a legal framework.','original'),
('113.31.d.13.A',3,'Since the Great Depression, the role of the federal government in the economy has what?','["Ended", "Shrunk to zero", "Disappeared", "Generally expanded"]'::jsonb,3,'The New Deal began broader involvement.','original'),
('113.31.d.13.B',3,'A cost of environmental regulation to a business can be what?','["Higher production costs", "Fewer rules", "Lower taxes", "Higher unemployment benefits"]'::jsonb,0,'Compliance can be costly.','original'),
('113.31.d.13.B',3,'A benefit of consumer-protection laws is what?','["More risk", "Safer products and fewer deceptive practices", "Fewer standards", "Higher fraud"]'::jsonb,1,'Rules protect consumers.','original'),
('113.31.d.14.A',2,'A sales tax is a tax on what?','["Income", "Imports only", "Purchases of goods and services", "Property"]'::jsonb,2,'Sales taxes are collected at the register.','original'),
('113.31.d.14.A',2,'Which tax is the largest source of federal revenue?','["Tariffs", "Property tax", "Sales tax", "The individual income tax"]'::jsonb,3,'Income taxes lead federal revenue.','original'),
('113.31.d.14.B',3,'Which is a major category of federal expenditures?','["Social Security and Medicare", "Allowances", "Tariff refunds", "Lottery winnings"]'::jsonb,0,'Mandatory spending is large.','original'),
('113.31.d.14.B',3,'A federal budget deficit occurs when what happens?','["Revenue exceeds spending", "Spending is greater than revenue", "Spending equals revenue", "Taxes are zero"]'::jsonb,1,'Borrowing covers the gap.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Social Studies' and d.language = 'en'
on conflict (fingerprint) do nothing;
