from (values
('113.31.d.14.C',3,'Cutting taxes to increase consumer spending is an example of what?','["Contractionary monetary policy", "A subsidy", "Expansionary fiscal policy", "A tariff"]'::jsonb,2,'Fiscal policy uses taxes and spending.','original'),
('113.31.d.14.C',3,'Raising taxes and cutting spending to slow inflation is an example of what?','["Free trade", "Expansionary policy", "Barter", "Contractionary fiscal policy"]'::jsonb,3,'It reduces demand.','original'),
('113.31.d.15.A',2,'A business owned and run by one person who is personally responsible for its debts is called what?','["A sole proprietorship", "A partnership of 50", "A cooperative", "A corporation"]'::jsonb,0,'The owner has unlimited liability.','original'),
('113.31.d.15.A',2,'A corporation''s owners are called what?','["Partners", "Shareholders", "Proprietors", "Depositors"]'::jsonb,1,'Owners hold shares of stock.','original'),
('113.31.d.15.B',3,'An advantage of a corporation over a sole proprietorship is what?','["Unlimited liability", "Easier setup", "Limited liability for owners", "Double taxation avoided"]'::jsonb,2,'Owners risk only their investment.','original'),
('113.31.d.15.B',3,'A disadvantage of a corporation is what?','["No owners", "No ability to raise capital", "No liability", "Profits may be taxed twice"]'::jsonb,3,'Corporate and dividend taxes.','original'),
('113.31.d.16.A',2,'A bank helps households and businesses by doing what?','["Holding deposits and making loans", "Printing money", "Owning homes", "Setting prices"]'::jsonb,0,'Banks connect savers and borrowers.','original'),
('113.31.d.16.A',3,'The FDIC insures bank deposits up to what amount per depositor, per bank, in each ownership category?','["$2 million", "$250,000", "$2,500", "$25,000"]'::jsonb,1,'The standard limit is $250,000.','original'),
('113.31.d.16.B',3,'Savings in an economy become capital formation when they are used to do what?','["Stay in cash", "Pay taxes", "Fund investment in factories, equipment and new businesses", "Buy imports"]'::jsonb,2,'Savings fund investment.','original'),
('113.31.d.16.B',3,'If a country''s savings rate rises, capital for businesses generally does what?','["Is banned", "Disappears", "Becomes scarce", "Becomes more available"]'::jsonb,3,'More loanable funds exist.','original'),
('113.31.d.16.C',3,'Which investment typically carries the highest risk and potential return?','["Stocks", "A government savings bond", "A savings account", "A CD"]'::jsonb,0,'Stocks vary widely in price.','original'),
('113.31.d.16.C',3,'Interest rates rise with risk because lenders need what?','["Fewer customers", "Compensation for the chance of loss", "Lower profit", "No security"]'::jsonb,1,'Higher risk calls for higher return.','original'),
('113.31.d.16.D',3,'A certificate of deposit usually pays a higher rate than a regular savings account because the money is what?','["Uninsured", "Free to withdraw anytime", "Locked up for a set term", "Risky"]'::jsonb,2,'Less liquidity earns more.','original'),
('113.31.d.16.D',3,'A risk of a money market account compared with a checking account is what?','["No interest", "No access ever", "No insurance", "Limits on transactions"]'::jsonb,3,'Transaction limits can apply.','original'),
('113.31.d.17.A',3,'A wise investor reduces risk by doing what?','["Diversifying across different investments", "Following rumors", "Avoiding research", "Putting all money in one stock"]'::jsonb,0,'Diversification spreads risk.','original'),
('113.31.d.17.A',3,'An index fund is useful for beginners because it does what?','["Guarantees returns", "Spreads investment across many companies at low cost", "Has no fees ever", "Buys one stock"]'::jsonb,1,'Funds are diversified.','original'),
('113.31.d.17.B',2,'A good way to begin a savings program is to do what?','["Spend first", "Save only leftovers", "Set a goal and save a fixed amount each paycheck", "Save nothing"]'::jsonb,2,'Regular saving builds habit.','original'),
('113.31.d.17.B',2,'An emergency fund should cover about how many months of expenses?','["10 years", "2 years", "1 day", "3 to 6 months"]'::jsonb,3,'A cushion for the unexpected.','original'),
('113.31.d.17.C',3,'An outstanding check is one that has been written but not yet what?','["Cleared by the bank", "Counted as income", "Deposited", "Signed"]'::jsonb,0,'It affects the bank balance until it clears.','original'),
('113.31.d.17.D',2,'A loan secured by the house being bought is called what?','["A payday loan", "A mortgage", "A scholarship", "A credit card"]'::jsonb,1,'The home is collateral.','original'),
('113.31.d.17.D',2,'Which type of loan is typically used to finance a car?','["A bond", "A student grant", "An installment auto loan", "A mortgage"]'::jsonb,2,'Cars are financed with installment loans.','original'),
('113.31.d.17.E',3,'A borrower''s responsibility on a loan includes what?','["Skipping payments", "Ignoring terms", "Paying whenever", "Repaying principal and interest on time"]'::jsonb,3,'Loans are legal obligations.','original'),
('113.31.d.17.E',3,'If a borrower defaults on a secured loan, the lender may do what?','["Take the collateral", "Pay the borrower", "Raise wages", "Forgive the loan"]'::jsonb,0,'Collateral secures the debt.','original'),
('113.31.d.17.F',3,'Paying bills on time raises your credit score because it does what?','["Hides debts", "Shows a history of reliability", "Closes accounts", "Raises interest"]'::jsonb,1,'Payment history is a major factor.','original'),
('113.31.d.17.F',3,'Keeping credit card balances well below the limit helps a credit score by doing what?','["Raising interest", "Hiding payments", "Lowering credit utilization", "Raising utilization"]'::jsonb,2,'Low utilization looks responsible.','original'),
('113.31.d.18.A',2,'The best way to avoid credit card debt is to do what?','["Take cash advances", "Pay the minimum", "Skip payments", "Pay the full balance each month"]'::jsonb,3,'Interest then never applies.','original'),
('113.31.d.18.A',3,'To pay off several cards faster, a strategy is to do what?','["Pay extra on the highest-interest card while paying minimums on the others", "Ignore interest", "Open more cards", "Pay only minimums"]'::jsonb,0,'Targeting high interest saves money.','original'),
('113.31.d.18.B',3,'One cost of declaring personal bankruptcy is what?','["Lower rates", "Damage to credit that can last up to 10 years", "A tax refund", "A raise"]'::jsonb,1,'It stays on a credit report for years.','original'),
('113.31.d.18.B',3,'One benefit of bankruptcy is that it can do what?','["Increase debts", "Guarantee a loan", "Discharge certain debts and stop collection actions", "Raise credit"]'::jsonb,2,'It offers a fresh start.','original'),
('113.31.d.18.C',3,'Insurance protects against financial loss by doing what?','["Ending taxes", "Raising risk", "Preventing accidents", "Spreading risk across many policyholders"]'::jsonb,3,'Premiums pool risk.','original'),
('113.31.d.18.C',3,'A higher deductible usually does what to the premium?','["Lowers it", "Raises it", "Cancels it", "Doubles it"]'::jsonb,0,'You take on more risk.','original'),
('113.31.d.18.D',3,'A benefit of charitable giving is what?','["It guarantees profit", "It can support a cause and may reduce taxable income", "It ends taxes", "It is required by law"]'::jsonb,1,'Donations may be deductible.','original'),
('113.31.d.18.D',3,'A cost of charitable giving is what?','["No cost at all", "Free goods", "Less money available for your own spending and saving", "Higher income"]'::jsonb,2,'Giving has an opportunity cost.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Social Studies' and d.language = 'en'
